{{$slide.button_label}}\r\n                    </a>\r\n\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n\r\n        {{ end }}\r\n\r\n    </div>\r\n\r\n    <!-- Previous -->\r\n    <button\r\n        id="prev-slide"\r\n        type="button"\r\n        class="absolute z-50 left-5 top-1/2 -translate-y-1/2\r\n               w-12 h-12 rounded-full\r\n               bg-black/40 hover:bg-black/70\r\n               text-white text-2xl\r\n               flex items-center justify-center\r\n               cursor-pointer transition">\r\n\r\n        ❮\r\n\r\n    </button>\r\n\r\n    <!-- Next -->\r\n    <button\r\n        id="next-slide"\r\n        type="button"\r\n        class="absolute z-50 right-5 top-1/2 -translate-y-1/2\r\n               w-12 h-12 rounded-full\r\n               bg-black/40 hover:bg-black/70\r\n               text-white text-2xl\r\n               flex items-center justify-center\r\n               cursor-pointer transition">\r\n\r\n        ❯\r\n\r\n    </button>\r\n\r\n</section>\r\n\r\n<script>\r\ndocument.addEventListener("DOMContentLoaded", function () {\r\n\r\n    const slides = document.querySelectorAll(".hero-slide");\r\n\r\n    if (!slides.length) return;\r\n\r\n    let current = 0;\r\n    let interval;\r\n\r\n    function showSlide(index) {\r\n\r\n        slides.forEach((slide, i) => {\r\n\r\n            if (i === index) {\r\n\r\n                slide.classList.remove(\r\n                    "opacity-0",\r\n                    "pointer-events-none",\r\n                    "z-0"\r\n                );\r\n\r\n                slide.classList.add(\r\n                    "opacity-100",\r\n                    "pointer-events-auto",\r\n                    "z-10"\r\n                );\r\n\r\n            } else {\r\n\r\n                slide.classList.remove(\r\n                    "opacity-100",\r\n                    "pointer-events-auto",\r\n                    "z-10"\r\n                );\r\n\r\n                slide.classList.add(\r\n                    "opacity-0",\r\n                    "pointer-events-none",\r\n                    "z-0"\r\n                );\r\n\r\n            }\r\n\r\n        });\r\n\r\n    }\r\n\r\n    function nextSlide() {\r\n\r\n        current = (current + 1) % slides.length;\r\n        showSlide(current);\r\n\r\n    }\r\n\r\n    function prevSlide() {\r\n\r\n        current = (current - 1 + slides.length) % slides.length;\r\n        showSlide(current);\r\n\r\n    }\r\n\r\n    function startAutoSlide() {\r\n\r\n        interval = setInterval(nextSlide, 5000);\r\n\r\n    }\r\n\r\n    function stopAutoSlide() {\r\n\r\n        clearInterval(interval);\r\n\r\n    }\r\n\r\n    document\r\n        .getElementById("next-slide")\r\n        .addEventListener("click", nextSlide);\r\n\r\n    document\r\n        .getElementById("prev-slide")\r\n        .addEventListener("click", prevSlide);\r\n\r\n    const hero = document.getElementById("hero-section");\r\n\r\n    hero.addEventListener("mouseenter", stopAutoSlide);\r\n    hero.addEventListener("mouseleave", startAutoSlide);\r\n\r\n    showSlide(current);\r\n    startAutoSlide();\r\n\r\n});\r\n</script>
1	header	{\r\n  "title": "string",\r\n  "logo": "string",\r\n  "links": [\r\n    {"label": "string", "url": "string"}\r\n  ]\r\n}\r\n	<style>\r\n        /* ====== Transitions & scroll ====== */\r\n        #social-header {\r\n            transition: transform 0.3s ease, opacity 0.3s ease;\r\n        }\r\n        #header {\r\n            transition: top 0.3s ease;\r\n        }\r\n\r\n        /* ====== Dropdowns (desktop) ====== */\r\n        .dropdown-menu {\r\n            display: none;\r\n            position: absolute;\r\n            left: 0;\r\n            top: 100%;\r\n            min-width: 260px;\r\n            background: #fff;\r\n            border: 1px solid #e5e7eb;\r\n            border-radius: 12px;\r\n            box-shadow: 0 10px 25px rgba(0, 0, 0, .08);\r\n            padding: 8px;\r\n            z-index: 60;\r\n            opacity: 0;\r\n            transform: translateY(-4px);\r\n            transition: opacity .2s ease, transform .2s ease;\r\n            pointer-events: none;\r\n        }\r\n        .dropdown-menu.open {\r\n            display: block;\r\n            opacity: 1;\r\n            transform: translateY(0);\r\n            pointer-events: auto;\r\n        }\r\n\r\n        /* ====== Sub-dropdowns ====== */\r\n        .sub-dropdown-menu {\r\n            display: none;\r\n            position: absolute;\r\n            left: calc(100% + 8px);\r\n            top: 0;\r\n            min-width: 260px;\r\n            background: #fff;\r\n            border: 1px solid #e5e7eb;\r\n            border-radius: 12px;\r\n            box-shadow: 0 10px 25px rgba(0, 0, 0, .08);\r\n            padding: 8px;\r\n            z-index: 70;\r\n            opacity: 0;\r\n            transform: translateX(-4px);\r\n            transition: opacity .2s ease, transform .2s ease;\r\n            pointer-events: none;\r\n        }\r\n        .sub-dropdown-menu.open {\r\n            display: block;\r\n            opacity: 1;\r\n            transform: translateX(0);\r\n            pointer-events: auto;\r\n        }\r\n\r\n        /* ====== Dropdown items ====== */\r\n        .dropdown-item,\r\n        .dropdown-item-sub {\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: space-between;\r\n            padding: 12px 18px;\r\n            border-radius: 8px;\r\n            font-size: 14px;\r\n            line-height: 1.5;\r\n            color: #374151;\r\n            white-space: nowrap;\r\n            cursor: pointer;\r\n            transition: background .15s ease, color .15s ease;\r\n        }\r\n        .dropdown-item:hover,\r\n        .dropdown-item-sub:hover {\r\n            background: #faf5ff;\r\n            color: #7e22ce;\r\n        }\r\n        .dropdown-item-sub.text-red-500 {\r\n            color: #ef4444;\r\n        }\r\n        .dropdown-item-sub.text-red-500:hover {\r\n            color: #dc2626;\r\n            background: #fef2f2;\r\n        }\r\n\r\n        /* ====== Mobile sidebar ====== */\r\n        #mobileSidebar {\r\n            position: fixed;\r\n            top: 0;\r\n            right: 0;\r\n            width: 300px;\r\n            max-width: 85vw;\r\n            height: 100%;\r\n            background: #fff;\r\n            z-index: 1000;\r\n            transform: translateX(100%);\r\n            transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);\r\n            overflow-y: auto;\r\n            padding: 1.25rem 1.5rem 2rem;\r\n            box-shadow: -8px 0 30px rgba(0, 0, 0, 0.12);\r\n        }\r\n        #mobileSidebar.open {\r\n            transform: translateX(0);\r\n        }\r\n\r\n        #sidebarOverlay {\r\n            position: fixed;\r\n            inset: 0;\r\n            background: rgba(0, 0, 0, 0.4);\r\n            z-index: 999;\r\n            opacity: 0;\r\n            pointer-events: none;\r\n            transition: opacity 0.3s ease;\r\n        }\r\n        #sidebarOverlay.open {\r\n            opacity: 1;\r\n            pointer-events: auto;\r\n        }\r\n\r\n        /* ====== Mobile accordion ====== */\r\n        .mobile-accordion-toggle .chevron {\r\n            transition: transform 0.25s ease;\r\n        }\r\n        .mobile-accordion-toggle.open .chevron {\r\n            transform: rotate(180deg);\r\n        }\r\n        .mobile-sub-list {\r\n            display: none;\r\n            padding-left: 1rem;\r\n            border-left: 2px solid #e5e7eb;\r\n            margin-left: 0.25rem;\r\n            margin-top: 0.25rem;\r\n        }\r\n        .mobile-sub-list.open {\r\n            display: block;\r\n        }\r\n\r\n        /* ====== Utilities ====== */\r\n        .nav-link-desktop {\r\n            font-weight: 500;\r\n            cursor: pointer;\r\n            user-select: none;\r\n            padding: 0.5rem 0;\r\n            white-space: nowrap;\r\n            color: #374151;\r\n            transition: color 0.2s ease;\r\n        }\r\n        .nav-link-desktop:hover {\r\n            color: #7e22ce;\r\n        }\r\n\r\n        /* Hamburger lines */\r\n        .hamburger-line {\r\n            display: block;\r\n            width: 26px;\r\n            height: 2.5px;\r\n            background: #1f2937;\r\n            border-radius: 4px;\r\n            transition: all 0.25s ease;\r\n            transform-origin: center;\r\n        }\r\n        .hamburger-line:not(:last-child) {\r\n            margin-bottom: 5px;\r\n        }\r\n        .hamburger.active .hamburger-line:nth-child(1) {\r\n            transform: translateY(7.5px) rotate(45deg);\r\n        }\r\n        .hamburger.active .hamburger-line:nth-child(2) {\r\n            opacity: 0;\r\n            transform: scaleX(0);\r\n        }\r\n        .hamburger.active .hamburger-line:nth-child(3) {\r\n            transform: translateY(-7.5px) rotate(-45deg);\r\n        }\r\n\r\n        /* Responsive */\r\n        @media (max-width: 1023px) {\r\n            .desktop-nav {\r\n                display: none !important;\r\n            }\r\n            .desktop-auth {\r\n                display: none !important;\r\n            }\r\n            .mobile-hamburger {\r\n                display: flex !important;\r\n            }\r\n        }\r\n        @media (min-width: 1024px) {\r\n            .mobile-hamburger {\r\n                display: none !important;\r\n            }\r\n            .desktop-nav {\r\n                display: flex !important;\r\n            }\r\n            .desktop-auth {\r\n                display: flex !important;\r\n            }\r\n        }\r\n\r\n        #mobileSidebar::-webkit-scrollbar {\r\n            width: 4px;\r\n        }\r\n        #mobileSidebar::-webkit-scrollbar-track {\r\n            background: #f1f1f1;\r\n        }\r\n        #mobileSidebar::-webkit-scrollbar-thumb {\r\n            background: #c4b5fd;\r\n            border-radius: 8px;\r\n        }\r\n\r\n        /* Fix for overlapping click areas */\r\n        .dropdown-menu .relative,\r\n        .sub-dropdown-menu .relative {\r\n            position: relative;\r\n        }\r\n    </style>\r\n\r\n    <!-- ====== SOCIAL HEADER ====== -->\r\n    <div id="social-header" class="fixed top-0 left-0 w-full bg-gradient-to-r from-pink-600 to-purple-600 text-white text-sm py-1 z-50">\r\n        <div class="container mx-auto flex justify-end gap-4 px-4">\r\n            <a href="#" class="hover:underline">📘 Facebook</a>\r\n            <a href="#" class="hover:underline">📸 Instagram</a>\r\n            <a href="#" class="hover:underline">💼 LinkedIn</a>\r\n            <a href="#" class="hover:underline">🐦 Twitter</a>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- ====== MAIN HEADER ====== -->\r\n    <header id="header" class="fixed top-[2.5rem] left-0 w-full bg-white shadow z-40">\r\n        <div class="container mx-auto flex items-center justify-between py-3 px-4">\r\n\r\n            <!-- Logo -->\r\n            <div class="flex items-center shrink-0">\r\n                <img src="/assets/logo.png" alt="Logo" class="h-10" />\r\n    