4z" clip-rule="evenodd" />\r\n                            </svg>\r\n                        </button>\r\n                        <div class="mobile-sub-list" data-accordion-content="productOnlineMobile">\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">SEO Services</a>\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Social Media Management</a>\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">PPC Advertising</a>\r\n                        </div>\r\n                    </div>\r\n                    <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Outdoor Advertising</a>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- Solution (mobile) -->\r\n            <div class="mobile-accordion">\r\n                <button class="mobile-accordion-toggle w-full flex items-center justify-between py-2.5 text-gray-800 font-medium hover:text-purple-600 transition-colors duration-200" data-accordion="solutionMobile">\r\n                    <span>Solution</span>\r\n                    <svg class="chevron w-4 h-4 text-gray-400 transition-transform duration-250" viewBox="0 0 20 20" fill="currentColor">\r\n                        <path fill-rule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clip-rule="evenodd" />\r\n                    </svg>\r\n                </button>\r\n                <div class="mobile-sub-list" data-accordion-content="solutionMobile">\r\n                    <!-- Messaging Services nested -->\r\n                    <div class="mobile-accordion">\r\n                        <button class="mobile-accordion-toggle w-full flex items-center justify-between py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200" data-accordion="solutionMessagingMobile">\r\n                            <span>Messaging Services</span>\r\n                            <svg class="chevron w-3.5 h-3.5 text-gray-400 transition-transform duration-250" viewBox="0 0 20 20" fill="currentColor">\r\n                                <path fill-rule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clip-rule="evenodd" />\r\n                            </svg>\r\n                        </button>\r\n                        <div class="mobile-sub-list" data-accordion-content="solutionMessagingMobile">\r\n                            <a href="#" class="block py-2 text-sm text-red-500 font-medium hover:text-red-600 transition-colors duration-200">★ SMS Advertising</a>\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Whatsapp Business Platform</a>\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Whatsapp Blast Tertarget</a>\r\n                        </div>\r\n                    </div>\r\n                    <!-- Online Services nested -->\r\n                    <div class="mobile-accordion">\r\n                        <button class="mobile-accordion-toggle w-full flex items-center justify-between py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200" data-accordion="solutionOnlineMobile">\r\n                            <span>Online Services</span>\r\n                            <svg class="chevron w-3.5 h-3.5 text-gray-400 transition-transform duration-250" viewBox="0 0 20 20" fill="currentColor">\r\n                                <path fill-rule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clip-rule="evenodd" />\r\n                            </svg>\r\n                        </button>\r\n                        <div class="mobile-sub-list" data-accordion-content="solutionOnlineMobile">\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Cloud Solutions</a>\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Data Analytics</a>\r\n                            <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">AI Integration</a>\r\n                        </div>\r\n                    </div>\r\n                    <a href="#" class="block py-2 text-sm text-gray-600 hover:text-purple-600 transition-colors duration-200">Outdoor Advertising</a>\r\n                </div>\r\n            </div>\r\n\r\n            <a href="#" class="block py-2.5 text-gray-800 font-medium hover:text-purple-600 transition-colors duration-200">Blog</a>\r\n            <a href="#" class="block py-2.5 text-gray-800 font-medium hover:text-purple-600 transition-colors duration-200">Affiliate</a>\r\n            <a href="#" class="block py-2.5 text-gray-800 font-medium hover:text-purple-600 transition-colors duration-200">Tutorial</a>\r\n\r\n            <hr class="my-4 border-gray-100" />\r\n\r\n            <a href="#" class="block py-2.5 text-gray-800 font-medium hover:text-purple-600 transition-colors duration-200">Register</a>\r\n            <a href="#" class="block py-2.5 text-gray-800 font-medium flex items-center gap-1 hover:text-purple-600 transition-colors duration-200">\r\n                <span>⇨</span> Login\r\n            </a>\r\n        </nav>\r\n    </div>\r\n\r\n    <!-- ====== JAVASCRIPT ====== -->\r\n    <script>\r\n        (function() {\r\n            'use strict';\r\n\r\n            // =============================================\r\n            // 1. SOCIAL HEADER SCROLL\r\n            // =============================================\r\n            const socialHeader = document.getElementById('social-header');\r\n            const header = document.getElementById('header');\r\n\r\n            function toggleSocial() {\r\n                if (window.scrollY === 0) {\r\n                    socialHeader.classList.remove('-translate-y-full', 'opacity-0');\r\n                    header.style.top = socialHeader.offsetHeight + 'px';\r\n                } else {\r\n                    socialHeader.classList.add('-translate-y-full', 'opacity-0');\r\n                    header.style.top = '0';\r\n                }\r\n            }\r\n            window.addEventListener('scroll', toggleSocial, { passive: true });\r\n            window.addEventListener('load', toggleSocial);\r\n            window.addEventListener('resize', toggleSocial);\r\n\r\n            // =============================================\r\n            // 2. DESKTOP DROPDOWNS — click to toggle\r\n            // =============================================\r\n            const dropdownTriggers = document.querySelectorAll('[data-dropdown-trigger]');\r\n\r\n            dropdownTriggers.forEach(trigger => {\r\n                const key = trigger.dataset.dropdownTrigger;\r\n                const menu = document.querySelector(`[data-dropdown-menu="${key}"]`);\r\n                if (!menu) return;\r\n\r\n                trigger.addEventListener('click', function(e) {\r\n                    e.stopPropagation();\r\n                    const isOpen = menu.classList.contains('open');\r\n\r\n                    // close all sibling dropdowns\r\n                    document.querySelectorAll('.dropdown-menu.open').forEach(m => {\r\n                        if (m !== menu) m.classList.remove('open');\r\n                    });\r\n\r\n                    if (isOpen) {\r\n                        menu.classList.remove('open');\r\n                        menu.querySelectorAll('.sub-dropdown-menu.open').forEach(sm => sm.classList.remove(\r\n                        'open'));\r\n                    } else {\r\n                        menu.classList.add('open');\r\n                    }\r\n                });\r\n\r\n                document.addEventListener('click', function(e) {\r\n                    const parent = trigger.closest('[data-dropdown]');\r\n                    if (parent && !parent.contains(e.target)) {\r\n                        menu.classList.remove('open');\r\n                        menu.querySelectorAll('.sub-dropdown-menu.open').forEach(sm => sm.classList.remove(\r\n                        'open'));\r\n                    }\r\n                });\r\n            });\r\n\r\n            // =============================================\r\n            // 3. DESKTOP SUB-DROPDOWNS\r\n            // =============================================\r\n            const subTriggers = document.querySelectorAll('[data-subdropdown-trigger]');\r\n\r\n            subTriggers.forEach(trigger => {\r\n                const key = trigger.dataset.subdropdownTrigger;\r\n                const subMenu = document.querySelector(`[data-subdropdown-menu="${key}"]`);\r\n                if (!subMenu) return;\r\n\r\n                trigger.addEventListener('click', function(e) {\r\n                    e.stopPropagation();\r\n                    const isOpen = subMenu.classList.contains('open');\r\n\r\n                    // Close other sub-menus inside the same parent dropdown\r\n                    const parentDropdown = trigger.closest('.dropdown-menu');\r\n                    if (parentDropdown) {\r\n                        parentDropdown.querySelectorAll('.sub-dropdown-menu.open').forEach(sm => {\r\n                            if (sm !== subMenu) sm.classList.remove('open');\r\n                        });\r\n                    }\r\n\r\n                    if (isOpen) {\r\n                        subMenu.classList.remove('open');\r\n                    } else {\r\n                        subMenu.classList.add('open');\r\n                    }\r\n                });\r\n\r\n                document.addEventListener('click', function(e) {\r\n                    const container = trigger.closest('.relative');\r\n                    if (container && !container.contains(e.target)) {\r\n                        subMenu.classList.remove('open');\r\n                    }\r\n                });\r\n            });\r\n\r\n            // =============================================\r\n            // 4. MOBILE SIDEBAR\r\n            // =============================================\r\n            const hamburgerBtn = document.getElementById('hamburgerBtn');\r\n            const closeSidebarBtn = document.getElementById('closeSidebarBtn');\r\n            const sidebar = document.getElementById('mobileSidebar');\r\n            const overlay = document.getElementById('sidebarOverlay');\r\n\r\n            function openSidebar() {\r\n                sidebar.classList.add('open');\r\n                overlay.classList.add('open');\r\n                document.body.style.overflow = 'hidden';\r\n                hamburgerBtn.classList.add('active');\r\n            }\r\n\r\n            function closeSidebar() {\r\n                sidebar.classList.remove('open');\r\n                overlay.classList.remove('open');\r\n                document.body.style.overflow = '';\r\n                hamburgerBtn.classList.remove('active');\r\n            }\r\n\r\n            hamburgerBtn.addEventListener('click', function(e) {\r\n                e.stopPropagation();\r\n                sidebar.classList.contains('open') ? closeSidebar() : openSidebar();\r\n            });\r\n\r\n            closeSidebarBtn.addEventListener('click', closeSidebar);\r\n            overlay.addEventListener('click', closeSidebar);\r\n\r\n            document.addEventListener('keydown', function(e) {\r\n                if (e.key === 'Escape' && sidebar.classList.contains('open')) closeSidebar();\r\n            });\r\n\r\n            // =============================================\r\n            // 5. MOBILE ACCORDION\r\n            // =============================================\r\n            const accordionToggles = document.querySelectorAll('[data-accordion]');\r\n\r\n            accordionToggles.forEach(toggle => {\r\n                const key = toggle.dataset.accordion;\r\n                const content = document.querySelector(`[data-accordion-content="${key}"]`);\r\n                if (!content) return;\r\n\r\n                toggle.addEventListener('click', function(e) {\r\n                    e.stopPropagation();\r\n                    const isOpen = content.classList.contains('open');\r\n                    if (isOpen) {\r\n                        content.classList.remove('open');\r\n                        toggle.classList.remove('open');\r\n                    } else {\r\n                        content.classList.add('open');\r\n                        toggle.classList.add('open');\r\n                    }\r\n                });\r\n            });\r\n\r\n            // =============================================\r\n            // 6. Close sidebar on link click\r\n            // =============================================\r\n            sidebar.querySelectorAll('a').forEach(link => {\r\n                link.addEventListener('click', function() {\r\n                    if (this.tagName === 'A') closeSidebar();\r\n                });\r\n            });\r\n\r\n            // =============================================\r\n            // 7. Close dropdowns when clicking outside\r\n            // =============================================\r\n            document.addEventListener('click', function(e) {\r\n                let clickedInside = false;\r\n                document.querySelectorAll('[data-dropdown]').forEach(dd => {\r\n                    if (dd.contains(e.target)) clickedInside = true;\r\n                });\r\n                if (!clickedInside) {\r\n                    document.querySelectorAll('.dropdown-menu.open').forEach(m => m.classList.remove('open'));\r\n                    document.querySelectorAll('.sub-dropdown-menu.open').forEach(sm => sm.classList.remove('open'));\r\n                }\r\n            });\r\n\r\n        })();\r\n    </script>
