ark .bg-white.rounded-xl.border button.bg-gray-100:hover {\r\n            background: #475569;\r\n        }\r\n\r\n        .dark header.bg-white\\/80 {\r\n            background: rgba(30, 41, 59, 0.85) !important;\r\n            backdrop-filter: blur(12px);\r\n            border-bottom-color: #334155 !important;\r\n        }\r\n        .dark header .text-gray-900 {\r\n            color: #f1f5f9 !important;\r\n        }\r\n        .dark header .text-gray-500 {\r\n            color: #94a3b8 !important;\r\n        }\r\n        .dark header .bg-gray-100 {\r\n            background: #334155 !important;\r\n        }\r\n        .dark header .bg-white.rounded-md {\r\n            background: #1e293b !important;\r\n            color: #f1f5f9 !important;\r\n        }\r\n        .dark header .text-gray-500.cursor-pointer {\r\n            color: #94a3b8 !important;\r\n        }\r\n        .dark header .text-gray-500.cursor-pointer:hover {\r\n            color: #e2e8f0 !important;\r\n        }\r\n        .dark header .bg-gray-200 {\r\n            background: #334155 !important;\r\n            color: #e2e8f0 !important;\r\n        }\r\n\r\n        /* Dark mode toggle button */\r\n        #themeToggle {\r\n            transition: all 0.2s;\r\n        }\r\n        #themeToggle:hover {\r\n            transform: scale(1.05);\r\n        }\r\n    </style>\r\n</head>\r\n<body class="transition-colors duration-300">\r\n    <!-- ===== MAIN ===== -->\r\n    <main class="w-full h-full">\r\n\r\n        <!-- Stats Grid -->\r\n        <div class="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">\r\n            <div class="stat-card dark:bg-slate-800 dark:border-slate-700">\r\n                <div class="flex items-center justify-between">\r\n                    <div class="stat-icon bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400"><i class="fas fa-bullhorn"></i></div>\r\n                    <span class="stat-change dark:bg-emerald-900/50 dark:text-emerald-300">+12%</span>\r\n        