sm text-gray-600 leading-relaxed mt-0.5">\r\n                                Semua Advertising agency yang menangani jasa promosi, dan branding bagi dunia usaha\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Enterprise -->\r\n                    <div class="flex gap-4">\r\n                        <div class="flex-shrink-0 w-10 h-10 rounded-full bg-green-100 text-green-600 flex items-center justify-center text-lg">\r\n                            <i class="fas fa-users"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h3 class="text-base font-bold text-gray-900 uppercase tracking-wide">ENTERPRISE</h3>\r\n                            <p class="text-sm text-gray-600 leading-relaxed mt-0.5">\r\n                                Seluruh usaha bisnis baik produk maupun jasa yang ingin mempromosikan usahanya.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- UMKM -->\r\n                    <div class="flex gap-4">\r\n                        <div class="flex-shrink-0 w-10 h-10 rounded-full bg-amber-100 text-amber-600 flex items-center justify-center text-lg">\r\n                            <i class="fas fa-store"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h3 class="text-base font-bold text-gray-900 uppercase tracking-wide">UMKM</h3>\r\n                            <p class="text-sm text-gray-600 leading-relaxed mt-0.5">\r\n                                Penggerak dan palaku UMKM yang ingin mencoba menggunakan pemasaran online.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Community / Personal -->\r\n                    <div class="flex gap-4">\r\n                        <div class="flex-shrink-0 w-10 h-10 rounded-full bg-purple-100 text-purple-600 flex items-center justify-center text-lg">\r\n                            <i class="fas fa-user-group"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h3 class="text-base font-bold text-gray-900 uppercase tracking-wide">COMMUNITY / PERSONAL</h3>\r\n                            <p class="text-sm text-gray-600 leading-relaxed mt-0.5">\r\n                                Baik komunitas atau perorangan yang ingin memperkenalkan ide dan jasa dan produknya secara digital.\r\n                            </p>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n\r\n                <!-- Image column (5/12) -->\r\n                <div class="md:col-span-3">\r\n                    <div class="relative w-full  overflow-hidden ">\r\n                        <img\r\n                            src="https://adsqoo.id/assets/images/about-us/Slide-SMS-Advertising.webp"\r\n                            alt="Slide SMS Advertising"\r\n                            class="w-full h-full object-cover"\r\n                            loading="lazy"\r\n                        />\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <!-- ========================================================== -->\r\n        <!-- ROW 4: Mengapa Harus Menggunakan Adsqoo? (3 cards)          -->\r\n        <!-- ========================================================== -->\r\n        <div class="mt-16 md:mt-20">\r\n            <h2 class="text-2xl md:text-3xl font-bold text-gray-900 text-center mb-10">\r\n                Mengapa Harus Menggunakan Adsqoo?\r\n            </h2>\r\n\r\n            <div class="grid grid-cols-1 md:grid-cols-3 gap-6">\r\n\r\n                <!-- Card 1 -->\r\n                <div class="bg-white rounded-2xl shadow-md hover:shadow-lg transition-shadow p-6 md:p-8 text-center border border-gray-100">\r\n