\"\\u003e750,000\\u003c/div\\u003e\\r\\n                                \\u003cdiv class=\\"sub\\"\\u003e\\u003ci class=\\"fas fa-users text-gray-400\\"\\u003e\\u003c/i\\u003e \\u003cspan id=\\"estFrequency\\"\\u003eFreq: 1.7x\\u003c/span\\u003e\\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n\\r\\n                    \\u003c!-- Tip --\\u003e\\r\\n                    \\u003cdiv class=\\"tip-box\\"\\u003e\\r\\n                        \\u003ci class=\\"fas fa-sparkles\\"\\u003e\\u003c/i\\u003e\\r\\n                        \\u003cdiv class=\\"content\\"\\u003e\\r\\n                            \\u003cstrong\\u003eOptimization Tip\\u003c/strong\\u003e\\u003cbr /\\u003e\\r\\n                            Your current targeting reaches a broad audience. Consider narrowing down locations for better ROI.\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n\\r\\n                \\u003c/div\\u003e\\r\\n            \\u003c/div\\u003e\\r\\n\\r\\n        \\u003c/div\\u003e\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n    \\u003c!-- ===== BOTTOM FIXED BAR ===== --\\u003e\\r\\n    \\u003cdiv class=\\"bottom-bar\\"\\u003e\\r\\n        \\u003cdiv class=\\"total-invest\\"\\u003e\\r\\n            \\u003cspan\\u003eTotal Investment\\u003c/span\\u003e\\r\\n            \\u003cstrong id=\\"bottomTotal\\"\\u003e$5,000\\u003c/strong\\u003e\\r\\n        \\u003c/div\\u003e\\r\\n        \\u003cdiv class=\\"actions flex items-center gap-3\\"\\u003e\\r\\n            \\u003cbutton class=\\"px-5 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 transition-colors border border-gray-300 rounded-lg hover:bg-gray-50\\"\\u003e\\r\\n                Save Draft\\r\\n            \\u003c/button\\u003e\\r\\n            \\u003cbutton id=\\"launchBtn\\" class=\\"px-6 py-2.5 rounded-lg text-sm font-semibold text-white transition-all duration-200 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 shadow-lg shadow-blue-200 hover:shadow-xl hover:shadow-blue-300 disabled:opacity-50 disabled:cursor-not-allowed\\"\\u003e\\r\\n                Launch Campaign\\r\\n            \\u003c/button\\u003e\\r\\n        \\u003c/div\\u003e\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n    \\u003c!-- ===== JAVASCRIPT ===== --\\u003e\\r\\n    \\u003cscript\\u003e\\r\\n        // ============================================================\\r\\n        //  DATA — Combined Programmatic into one option\\r\\n        // ============================================================\\r\\n\\r\\n        const CAMPAIGN_TYPES = [\\r\\n            { id: 'whatsapp', name: 'WhatsApp', icon: 'fa-brands fa-whatsapp', color: '#25D366', category: 'messaging' },\\r\\n            { id: 'sms', name: 'SMS', icon: 'fas fa-mobile-alt', color: '#3B82F6', category: 'messaging' },\\r\\n            { id: 'rcs', name: 'RCS', icon: 'fas fa-comment', color: '#F59E0B', category: 'messaging' },\\r\\n            { id: 'ooh', name: 'OOH', icon: 'fas fa-building', color: '#10B981', category: 'outdoor' },\\r\\n            { id: 'dooh', name: 'DOOH', icon: 'fas fa-desktop', color: '#8B5CF6', category: 'outdoor' },\\r\\n            // Combined Programmatic\\r\\n            { id: 'programmatic', name: 'Programmatic Ads', icon: 'fas fa-ad', color: '#F97316', category: 'programmatic' },\\r\\n            { id: 'meta', name: 'Meta Ads', icon: 'fa-brands fa-facebook', color: '#1877F2', category: 'social' },\\r\\n            { id: 'gdn', name: 'YouTube', icon: 'fa-brands fa-youtube', color: '#FF0000', category: 'social' },\\r\\n            { id: 'tiktok', name: 'TikTok', icon: 'fa-brands fa-tiktok', color: '#000000', category: 'social' },\\r\\n        ];\\r\\n\\r\\n        const DEMOGRAPHICS = [\\r\\n            { id: '18-24', label: '18-24', multiplier: 1.0 },\\r\\n            { id: '25-34', label: '25-34', multiplier: 1.1 },\\r\\n            { id: '35-44', label: '35-44', multiplier: 1.2 },\\r\\n            { id: '45-54', label: '45-54', multiplier: 1.1 },\\r\\n            { id: '55-64', label: '55-64', multiplier: 0.9 },\\r\\n            { id: '65+', label: '65+', multiplier: 0.8 },\\r\\n        ];\\r\\n\\r\\n        const GENDERS = [\\r\\n            { id: 'all', label: 'All' },\\r\\n            { id: 'male', label: 'Male' },\\r\\n            { id: 'female', label: 'Female' },\\r\\n        ];\\r\\n\\r\\n        const LOCATIONS = [\\r\\n            { id: 'us', label: 'US', multiplier: 1.5 },\\r\\n            { id: 'uk', label: 'UK', multiplier: 1.4 },\\r\\n            { id: 'de', label: 'DE', multiplier: 1.3 },\\r\\n            { id: 'fr', label: 'FR', multiplier: 1.2 },\\r\\n            { id: 'id', label: 'ID', multiplier: 0.6 },\\r\\n            { id: 'sg', label: 'SG', multiplier: 1.4 },\\r\\n            { id: 'my', label: 'MY', multiplier: 0.7 },\\r\\n            { id: 'th', label: 'TH', multiplier: 0.6 },\\r\\n            { id: 'ph', label: 'PH', multiplier: 0.5 },\\r\\n            { id: 'global', label: 'Global', multiplier: 1.0 },\\r\\n        ];\\r\\n\\r\\n        const INTERESTS = ['technology', 'lifestyle', 'fashion', 'sports', 'travel', 'food', 'music', 'gaming'];\\r\\n\\r\\n        const BASE_CPM_RATES = {\\r\\n            whatsapp: 0.05,\\r\\n            sms: 0.03,\\r\\n            rcs: 0.08,\\r\\n            ooh: 15,\\r\\n            dooh: 25,\\r\\n            programmatic: 3.5, // blended rate for combined programmatic\\r\\n            meta: 8,\\r\\n            gdn: 3,\\r\\n            tiktok: 6,\\r\\n        };\\r\\n\\r\\n        const SAMPLE_IMAGES = [\\r\\n            'https://images.unsplash.com/photo-1557804506-669a67965ba0?w=600\\u0026h=400\\u0026fit=crop',\\r\\n            'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600\\u0026h=400\\u0026fit=crop',\\r\\n            'https://images.unsplash.com/photo-1551434678-e076c223a692?w=600\\u0026h=400\\u0026fit=crop',\\r\\n            'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=600\\u0026h=400\\u0026fit=crop',\\r\\n        ];\\r\\n\\r\\n        // ============================================================\\r\\n        //  STATE\\r\\n        // ============================================================\\r\\n\\r\\n        const state = {\\r\\n            type: 'meta',\\r\\n            activeTab: 'all',\\r\\n            name: 'Summer Blast 2024',\\r\\n            objective: 'engagement',\\r\\n            startDate: '',\\r\\n            endDate: '',\\r\\n            budget: 5000,\\r\\n            demographics: ['25-34', '35-44'],\\r\\n            gender: 'all',\\r\\n            locations: ['us', 'uk'],\\r\\n            interests: ['technology', 'lifestyle'],\\r\\n            headline: 'Transform Your Business Today',\\r\\n            description: 'Discover innovative solutions that help you grow faster and reach more customers effortlessly.',\\r\\n            ctaText: 'Learn More',\\r\\n            mediaUrl: '',\\r\\n            isSubmitting: false,\\r\\n        };\\r\\n\\r\\n        // ============================================================\\r\\n        //  HELPERS\\r\\n        // ============================================================\\r\\n\\r\\n        function fmt(n) { return n.toLocaleString(); }\\r\\n\\r\\n        function pad(n) { return String(n).padStart(2, '0'); }\\r\\n\\r\\n        function formatDate(d) {\\r\\n            return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());\\r\\n        }\\r\\n\\r\\n        function addDays(d, n) {\\r\\n            const r = new Date(d);\\r\\n            r.setDate(r.getDate() + n);\\r\\n            return r;\\r\\n        }\\r\\n\\r\\n        function daysBetween(a, b) {\\r\\n            return Math.max(1, Math.ceil((b.getTime() - a.getTime()) / (1000 * 60 * 60 * 24)));\\r\\n        }\\r\\n\\r\\n        function getSelectedType() {\\r\\n            return CAMPAIGN_TYPES.find(t =\\u003e t.id === state.type) || CAMPAIGN_TYPES[0];\\r\\n        }\\r\\n\\r\\n        function getFilteredTypes() {\\r\\n            return state.activeTab === 'all' ?\\r\\n                CAMPAIGN_TYPES :\\r\\n                CAMPAIGN_TYPES.filter(t =\\u003e t.category === state.activeTab);\\r\\n        }\\r\\n\\r\\n        function calculateMetrics() {\\r\\n            const baseCpm = BASE_CPM_RATES[state.type] || 5;\\r\\n            const start = new Date(state.startDate);\\r\\n            const end = new Date(state.endDate);\\r\\n            const days = daysBetween(start, end);\\r\\n\\r\\n            let multiplier = 1;\\r\\n            const demoMult = state.demographics.map(d =\\u003e DEMOGRAPHICS.find(dm =\\u003e dm.id === d)?.multiplier || 1);\\r\\n            multiplier *= demoMult.length \\u003e 0 ? demoMult.reduce((a, b) =\\u003e a + b, 0) / demoMult.length : 1;\\r\\n\\r\\n            const locMult = state.locations.map(l =\\u003e LOCATIONS.find(lm =\\u003e lm.id === l)?.multiplier || 1);\\r\\n            multiplier *= locMult.length \\u003e 0 ? Math.max(...locMult) : 1;\\r\\n\\r\\n            const finalCpm = baseCpm * multiplier;\\r\\n            const impressions = Math.round((state.budget / finalCpm) * 1000);\\r\\n            const reach = Math.round(impressions * 0.6);\\r\\n            const frequency = (impressions / reach).toFixed(1);\\r\\n\\r\\n            return {\\r\\n                cpm: finalCpm.toFixed(2),\\r\\n                impressions,\\r\\n                reach,\\r\\n                frequency,\\r\\n                dailyBudget: Math.round(state.budget / days),\\r\\n                days,\\r\\n            };\\r\\n        }\\r\\n\\r\\n        function toggleItem(arr, item) {\\r\\n            return arr.includes(item) ? arr.filter(x =\\u003e x !== item) : [...arr, item];\\r\\n        }\\r\\n\\r\\n        // ============================================================\\r\\n        //  RENDER FUNCTIONS\\r\\n        // ============================================================\\r\\n\\r\\n        function renderChannelGrid() {\\r\\n            const grid = document.getElementById('channelGrid');\\r\\n            const types = getFilteredTypes();\\r\\n            const selected = state.type;\\r\\n\\r\\n            grid.innerHTML = types.map(t =\\u003e {\\r\\n                const active = selected === t.id;\\r\\n                return `\\r\\n                    \\u003cbutton data-channel=\\"${t.id}\\" class=\\"channel-btn ${active ? 'active' : ''}\\"\\u003e\\r\\n                        \\u003cdiv class=\\"icon-wrap\\" style=\\"background:${t.color}15;color:${t.color}\\"\\u003e\\r\\n                            \\u003ci class=\\"${t.icon}\\"\\u003e\\u003c/i\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                        \\u003cspan style=\\"font-size:10px;display:block;line-height:1.2\\"\\u003e${t.name}\\u003c/span\\u003e\\r\\n                        ${active ? `\\u003cspan class=\\"check\\"\\u003e\\u003ci class=\\"fas fa-check\\"\\u003e\\u003c/i\\u003e\\u003c/span\\u003e` : ''}\\r\\n                    \\u003c/button\\u003e\\r\\n                `;\\r\\n            }).join('');\\r\\n\\r\\n            grid.querySelectorAll('[data-channel]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.type = btn.dataset.channel;\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderDemographics() {\\r\\n            const container = document.getElementById('ageGroup');\\r\\n            container.innerHTML = DEMOGRAPHICS.map(d =\\u003e {\\r\\n                const active = state.demographics.includes(d.id);\\r\\n                return `\\u003cbutton data-demo=\\"${d.id}\\" class=\\"chip ${active ? 'active' : ''}\\"\\u003e${d.label}\\u003c/button\\u003e`;\\r\\n            }).join('');\\r\\n            container.querySelectorAll('[data-demo]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.demographics = toggleItem(state.demographics, btn.dataset.demo);\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderGenders() {\\r\\n            const container = document.getElementById('genderGroup');\\r\\n            container.innerHTML = GENDERS.map(g =\\u003e {\\r\\n                const active = state.gender === g.id;\\r\\n                return `\\u003cbutton data-gender=\\"${g.id}\\" class=\\"chip ${active ? 'active' : ''}\\"\\u003e${g.label}\\u003c/button\\u003e`;\\r\\n            }).join('');\\r\\n            container.querySelectorAll('[data-gender]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.gender = btn.dataset.gender;\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderLocations() {\\r\\n            const container = document.getElementById('locationGroup');\\r\\n            container.innerHTML = LOCATIONS.map(l =\\u003e {\\r\\n                const active = state.locations.includes(l.id);\\r\\n                return `\\u003cbutton data-loc=\\"${l.id}\\" class=\\"chip ${active ? 'active-indigo' : ''}\\"\\u003e${l.label}\\u003c/button\\u003e`;\\r\\n            }).join('');\\r\\n            container.querySelectorAll('[data-loc]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.locations = toggleItem(state.locations, btn.dataset.loc);\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderInterests() {\\r\\n            const container = document.getElementById('interestGroup');\\r\\n            container.innerHTML = INTERESTS.map(i =\\u003e {\\r\\n                const active = state.interests.includes(i);\\r\\n                return `\\u003cbutton data-interest=\\"${i}\\" class=\\"chip ${active ? 'active-purple' : ''}\\"\\u003e${i}\\u003c/button\\u003e`;\\r\\n            }).join('');\\r\\n            container.querySelectorAll('[data-interest]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.interests = toggleItem(state.interests, btn.dataset.interest);\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        // ============================================================\\r\\n        //  PREVIEW RENDERERS\\r\\n        // ============================================================\\r\\n\\r\\n        function renderWhatsApp() {\\r\\n            const d = state;\\r\\n            return `\\r\\n                \\u003cdiv class=\\"phone-mockup w-64 mx-auto\\" style=\\"max-width:100%\\"\\u003e\\r\\n                    \\u003cdiv class=\\"phone-screen\\" style=\\"min-height:260px\\"\\u003e\\r\\n                        \\u003cdiv class=\\"bg-[#25D366] p-2 flex items-center gap-2\\"\\u003e\\r\\n                            \\u003ci class=\\"fas fa-comment text-white text-sm\\"\\u003e\\u003c/i\\u003e\\r\\n                            \\u003cspan class=\\"text-white font-semibold text-xs\\"\\u003eWhatsApp\\u003c/span\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"p-3\\"\\u003e\\r\\n                            \\u003cdiv class=\\"bg-gray-100 rounded-lg p-2 max-w-[85%]\\"\\u003e\\r\\n                                \\u003cp class=\\"text-xs text-gray-800 font-medium\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                                \\u003cp class=\\"text-[10px] text-gray-600 mt-0.5\\"\\u003e${d.description.slice(0,60)}${d.description.length\\u003e60?'...':''}\\u003c/p\\u003e\\r\\n                                ${d.mediaUrl ? `\\u003cimg src=\\"${d.mediaUrl}\\" class=\\"mt-1 rounded w-full h-12 object-cover\\" /\\u003e` : ''}\\r\\n                                \\u003cbutton class=\\"mt-1 w-full bg-[#25D366] text-white text-[10px] py-1.5 rounded-full\\"\\u003e${d.ctaText}\\u003c/button\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n            `;\\r\\n        }\\r\\n\\r\\n        function renderSMS() {\\r\\n            const d = state;\\r\\n            return `\\r\\n                \\u003cdiv class=\\"phone-mockup w-64 mx-auto\\" style=\\"max-width:100%\\"\\u003e\\r\\n                    \\u003cdiv class=\\"phone-screen\\" style=\\"min-height:260px\\"\\u003e\\r\\n                        \\u003cdiv class=\\"notch\\" style=\\"width:80px;height:18px\\"\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"p-3\\"\\u003e\\r\\n                            \\u003cdiv class=\\"text-center text-[10px] text-gray-400 mb-2\\"\\u003eToday 2:30 PM\\u003c/div\\u003e\\r\\n                            \\u003cdiv class=\\"bg-[#3B82F6] text-white rounded-2xl rounded-tl-sm p-3 max-w-[90%] ml-auto\\"\\u003e\\r\\n                                \\u003cp class=\\"text-xs font-medium\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                                \\u003cp class=\\"text-[10px] mt-0.5 opacity-90\\"\\u003e${d.description.slice(0,80)}${d.description.length\\u003e80?'...':''}\\u003c/p\\u003e\\r\\n                                \\u003cp class=\\"text-[10px] mt-1 underline\\"\\u003eReply STOP\\u003c/p\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n            `;\\r\\n        }\\r\\n\\r\\n        function renderMeta() {\\r\\n            const d = state;\\r\\n            return `\\r\\n                \\u003cdiv class=\\"bg-white rounded-lg shadow-md overflow-hidden max-w-xs mx-auto border border-gray-200\\" style=\\"max-width:280px\\"\\u003e\\r\\n                    \\u003cdiv class=\\"flex items-center gap-2 p-2 border-b\\"\\u003e\\r\\n                        \\u003cdiv class=\\"w-7 h-7 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white font-bold text-[10px]\\"\\u003eYB\\u003c/div\\u003e\\r\\n                        \\u003cdiv\\u003e\\u003cp class=\\"text-xs font-semibold\\"\\u003eYour Brand\\u003c/p\\u003e\\u003cp class=\\"text-[9px] text-gray-500\\"\\u003eSponsored\\u003c/p\\u003e\\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                    \\u003cp class=\\"p-2 text-xs\\"\\u003e${d.description.slice(0,80)}${d.description.length\\u003e80?'...':''}\\u003c/p\\u003e\\r\\n                    ${d.mediaUrl ? `\\u003cimg src=\\"${d.mediaUrl}\\" class=\\"w-full h-28 object-cover\\" /\\u003e` : `\\u003cdiv class=\\"w-full h-28 bg-gray-100 flex items-center justify-center\\"\\u003e\\u003ci class=\\"fas fa-image text-gray-300 text-2xl\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e`}\\r\\n                    \\u003cdiv class=\\"p-2 border-t flex items-center justify-between\\"\\u003e\\r\\n                        \\u003cdiv\\u003e\\u003cp class=\\"text-xs font-semibold\\"\\u003e${d.headline}\\u003c/p\\u003e\\u003cp class=\\"text-[9px] text-gray-500\\"\\u003eyourbrand.com\\u003c/p\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cbutton class=\\"bg-[#1877F2] text-white text-[10px] px-3 py-1 rounded font-medium\\"\\u003e${d.ctaText}\\u003c/button\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n            `;\\r\\n        }\\r\\n\\r\\n        function renderTikTok() {\\r\\n            const d = state;\\r\\n            return `\\r\\n                \\u003cdiv class=\\"phone-mockup w-64 mx-auto\\" style=\\"max-width:100%\\"\\u003e\\r\\n                    \\u003cdiv class=\\"phone-screen relative\\" style=\\"min-height:280px\\"\\u003e\\r\\n                        \\u003cdiv class=\\"absolute top-0 left-0 right-0 p-2 flex justify-between z-10\\"\\u003e\\r\\n                            \\u003cspan class=\\"text-white text-xs font-semibold drop-shadow\\"\\u003eFollowing\\u003c/span\\u003e\\r\\n                            \\u003cspan class=\\"text-white text-xs font-semibold drop-shadow\\"\\u003eFor You\\u003c/span\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"relative h-72 bg-gradient-to-b from-gray-900 to-black\\"\\u003e\\r\\n                            ${d.mediaUrl ? `\\u003cimg src=\\"${d.mediaUrl}\\" class=\\"w-full h-full object-cover opacity-80\\" /\\u003e` : `\\u003cdiv class=\\"w-full h-full flex items-center justify-center\\"\\u003e\\u003ci class=\\"fas fa-video text-gray-600 text-3xl\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e`}\\r\\n                            \\u003cdiv class=\\"absolute bottom-0 left-0 right-0 p-3 bg-gradient-to-t from-black/80 to-transparent\\"\\u003e\\r\\n                                \\u003cp class=\\"text-white text-xs font-semibold\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                                \\u003cp class=\\"text-white/70 text-[10px]\\"\\u003e${d.description.slice(0,50)}${d.description.length\\u003e50?'...':''}\\u003c/p\\u003e\\r\\n                                \\u003cdiv class=\\"mt-1\\"\\u003e\\u003cspan class=\\"bg-white/20 backdrop-blur text-white text-[10px] px-3 py-0.5 rounded-full\\"\\u003e${d.ctaText}\\u003c/span\\u003e\\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n            `;\\r\\n        }\\r\\n\\r\\n        function renderYouTube() {\\r\\n            const d = state;\\r\\n            return `\\r\\n                \\u003cdiv class=\\"bg-white rounded-lg shadow-md overflow-hidden max-w-xs mx-auto border border-gray-200\\" style=\\"max-width:300px\\"\\u003e\\r\\n                    \\u003cdiv class=\\"relative aspect-video bg-black\\"\\u003e\\r\\n                        ${d.mediaUrl ? `\\u003cimg src=\\"${d.mediaUrl}\\" class=\\"w-full h-full object-cover\\" /\\u003e` : `\\u003cdiv class=\\"w-full h-full flex items-center justify-center\\"\\u003e\\u003ci class=\\"fas fa-play text-gray-400 text-3xl\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e`}\\r\\n                        \\u003cdiv class=\\"absolute bottom-1 right-1 bg-black/80 text-white text-[9px] px-1.5 py-0.5 rounded\\"\\u003e0:15\\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"absolute bottom-0 left-0 right-0 h-0.5 bg-gray-700\\"\\u003e\\u003cdiv class=\\"h-full bg-red-600 w-1/4\\"\\u003e\\u003c/div\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/90 to-transparent p-2\\"\\u003e\\r\\n                            \\u003cp class=\\"text-white text-xs font-semibold\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                            \\u003cbutton class=\\"mt-1 bg-white text-black text-[10px] px-3 py-0.5 rounded-full font-medium\\"\\u003e${d.ctaText}\\u003c/button\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                    \\u003cdiv class=\\"p-2 flex gap-2\\"\\u003e\\r\\n                        \\u003cdiv class=\\"w-7 h-7 rounded-full bg-red-600 flex items-center justify-center\\"\\u003e\\u003ci class=\\"fas fa-play text-white text-[8px]\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"flex-1\\"\\u003e\\u003cp class=\\"text-xs font-semibold line-clamp-1\\"\\u003e${d.headline}\\u003c/p\\u003e\\u003cp class=\\"text-[9px] text-gray-500\\"\\u003eYour Brand • Sponsored\\u003c/p\\u003e\\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n            `;\\r\\n        }\\r\\n\\r\\n        // Generic Programmatic Ad preview (combines banner + video style)\\r\\n        function renderProgrammatic() {\\r\\n            const d = state;\\r\\n            return `\\r\\n                \\u003cdiv class=\\"bg-white rounded-lg shadow-md overflow-hidden max-w-xs mx-auto border border-gray-200\\" style=\\"max-width:280px\\"\\u003e\\r\\n                    \\u003cdiv class=\\"relative\\"\\u003e\\r\\n                        ${d.mediaUrl ? `\\r\\n                            \\u003cdiv class=\\"relative\\"\\u003e\\r\\n                                \\u003cimg src=\\"${d.mediaUrl}\\" class=\\"w-full h-32 object-cover\\" /\\u003e\\r\\n                                \\u003cdiv class=\\"absolute inset-0 flex items-center justify-center bg-black/10\\"\\u003e\\r\\n                                    \\u003cdiv class=\\"w-10 h-10 rounded-full bg-white/80 flex items-center justify-center\\"\\u003e\\r\\n                                        \\u003ci class=\\"fas fa-play text-gray-700 text-sm ml-0.5\\"\\u003e\\u003c/i\\u003e\\r\\n                                    \\u003c/div\\u003e\\r\\n                                \\u003c/div\\u003e\\r\\n                                \\u003cdiv class=\\"absolute bottom-1 right-1 bg-black/60 text-white text-[8px] px-1.5 py-0.5 rounded\\"\\u003e0:30\\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        ` : `\\r\\n                            \\u003cdiv class=\\"h-32 bg-gradient-to-br from-orange-100 to-amber-100 flex items-center justify-center\\"\\u003e\\r\\n                                \\u003ci class=\\"fas fa-ad text-3xl text-orange-400\\"\\u003e\\u003c/i\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        `}\\r\\n                        \\u003cdiv class=\\"absolute top-1 left-1\\"\\u003e\\u003cspan class=\\"bg-black/50 text-white text-[8px] px-1.5 py-0.5 rounded backdrop-blur\\"\\u003eAd\\u003c/span\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"absolute bottom-1 left-1 right-1\\"\\u003e\\r\\n                            \\u003cdiv class=\\"bg-white/90 backdrop-blur rounded p-1.5 flex items-center gap-2\\"\\u003e\\r\\n                                \\u003ci class=\\"fas fa-mouse-pointer text-orange-500 text-[10px]\\"\\u003e\\u003c/i\\u003e\\r\\n                                \\u003cspan class=\\"text-[9px] font-medium text-gray-700\\"\\u003eProgrammatic Display\\u003c/span\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                    \\u003cdiv class=\\"p-2\\"\\u003e\\r\\n                        \\u003cp class=\\"text-xs font-semibold text-orange-600\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                        \\u003cp class=\\"text-[10px] text-gray-600 line-clamp-1\\"\\u003e${d.description}\\u003c/p\\u003e\\r\\n                        \\u003cdiv class=\\"mt-1 flex items-center justify-between\\"\\u003e\\r\\n                            \\u003cspan class=\\"text-[9px] text-gray-400\\"\\u003eyourbrand.com\\u003c/span\\u003e\\r\\n                            \\u003cbutton class=\\"bg-orange-500 text-white text-[10px] px-3 py-0.5 rounded hover:bg-orange-600 transition-colors\\"\\u003e${d.ctaText}\\u003c/button\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n            `;\\r\\n        }\\r\\n\\r\\n        function renderOOH(isDigital) {\\r\\n            const d = state;\\r\\n            if (isDigital) {\\r\\n                return `\\r\\n                    \\u003cdiv class=\\"relative mx-auto\\" style=\\"max-width:320px\\"\\u003e\\r\\n                        \\u003cdiv class=\\"bg-gray-900 rounded-lg p-1.5 shadow-xl\\"\\u003e\\r\\n                            \\u003cdiv class=\\"aspect-video bg-black rounded overflow-hidden relative\\"\\u003e\\r\\n                                ${d.mediaUrl ? `\\u003cimg src=\\"${d.mediaUrl}\\" class=\\"w-full h-full object-cover\\" /\\u003e` : `\\u003cdiv class=\\"w-full h-full bg-gradient-to-br from-violet-900 to-blue-900 flex items-center justify-center\\"\\u003e\\u003ci class=\\"fas fa-desktop text-white/20 text-3xl\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e`}\\r\\n                                \\u003cdiv class=\\"absolute inset-0 flex flex-col items-center justify-center text-center p-4\\"\\u003e\\r\\n                                    \\u003cp class=\\"text-white text-lg font-bold\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                                    \\u003cp class=\\"text-white/70 text-[10px]\\"\\u003e${d.description.slice(0,40)}${d.description.length\\u003e40?'...':''}\\u003c/p\\u003e\\r\\n                                    \\u003cspan class=\\"mt-1 bg-white text-black px-4 py-1 rounded-full text-[10px] font-semibold\\"\\u003e${d.ctaText}\\u003c/span\\u003e\\r\\n                                \\u003c/div\\u003e\\r\\n                                \\u003cdiv class=\\"absolute bottom-1 right-1 flex items-center gap-1\\"\\u003e\\r\\n                                    \\u003cdiv class=\\"w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse\\"\\u003e\\u003c/div\\u003e\\r\\n                                    \\u003cspan class=\\"text-white/50 text-[8px]\\"\\u003eLive\\u003c/span\\u003e\\r\\n                                \\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                `;\\r\\n            } else {\\r\\n                return `\\r\\n                    \\u003cdiv class=\\"relative mx-auto\\" style=\\"max-width:320px\\"\\u003e\\r\\n                        \\u003cdiv class=\\"bg-gray-800 rounded-lg p-2 shadow-xl\\"\\u003e\\r\\n                            \\u003cdiv class=\\"aspect-[4/3] bg-white rounded overflow-hidden relative\\"\\u003e\\r\\n                                ${d.mediaUrl ? `\\u003cimg src=\\"${d.mediaUrl}\\" class=\\"w-full h-full object-cover\\" /\\u003e` : `\\u003cdiv class=\\"w-full h-full bg-gradient-to-br from-emerald-500 to-teal-600\\"\\u003e\\u003c/div\\u003e`}\\r\\n                                \\u003cdiv class=\\"absolute inset-0 flex flex-col items-center justify-center text-center p-4\\"\\u003e\\r\\n                                    \\u003cp class=\\"text-2xl font-bold text-white drop-shadow-lg\\"\\u003e${d.headline}\\u003c/p\\u003e\\r\\n                                    \\u003cp class=\\"text-white/80 text-[10px]\\"\\u003e${d.description.slice(0,40)}${d.description.length\\u003e40?'...':''}\\u003c/p\\u003e\\r\\n                                \\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"absolute -bottom-2 left-1/2 -translate-x-1/2 flex gap-1\\"\\u003e\\r\\n                            \\u003cdiv class=\\"w-10 h-2 bg-gray-700 rounded-b\\"\\u003e\\u003c/div\\u003e\\r\\n                            \\u003cdiv class=\\"w-10 h-2 bg-gray-700 rounded-b\\"\\u003e\\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                `;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        function renderPreview() {\\r\\n            const container = document.getElementById('previewContainer');\\r\\n            const type = state.type;\\r\\n            let html = '';\\r\\n            switch (type) {\\r\\n                case 'whatsapp':\\r\\n                    html = renderWhatsApp();\\r\\n                    break;\\r\\n                case 'sms':\\r\\n                    html = renderSMS();\\r\\n                    break;\\r\\n                case 'rcs':\\r\\n                case 'meta':\\r\\n                    html = renderMeta();\\r\\n                    break;\\r\\n                case 'tiktok':\\r\\n                    html = renderTikTok();\\r\\n                    break;\\r\\n                case 'gdn':\\r\\n                    html = renderYouTube();\\r\\n                    break;\\r\\n                case 'programmatic':\\r\\n                    html = renderProgrammatic();\\r\\n                    break;\\r\\n                case 'ooh':\\r\\n                    html = renderOOH(false);\\r\\n                    break;\\r\\n                case 'dooh':\\r\\n                    html = renderOOH(true);\\r\\n                    break;\\r\\n                default:\\r\\n                    html = renderMeta();\\r\\n            }\\r\\n            container.innerHTML = html;\\r\\n            const sel = getSelectedType();\\r\\n            document.getElementById('previewChannelName').textContent = sel.name;\\r\\n            document.getElementById('previewDot').style.backgroundColor = sel.color;\\r\\n        }\\r\\n\\r\\n        // ============================================================\\r\\n        //  UPDATE UI\\r\\n        // ============================================================\\r\\n\\r\\n        function updateAll() {\\r\\n            renderChannelGrid();\\r\\n            renderDemographics();\\r\\n            renderGenders();\\r\\n            renderLocations();\\r\\n            renderInterests();\\r\\n            renderPreview();\\r\\n            updateSummary();\\r\\n            updateMetrics();\\r\\n\\r\\n            document.getElementById('budgetDisplay').textContent = fmt(state.budget);\\r\\n            document.getElementById('budgetRange').value = state.budget;\\r\\n            document.getElementById('bottomTotal').textContent = '$' + fmt(state.budget);\\r\\n\\r\\n            document.getElementById('campaignName').value = state.name;\\r\\n            document.getElementById('campaignObjective').value = state.objective;\\r\\n            document.getElementById('headline').value = state.headline;\\r\\n            document.getElementById('description').value = state.description;\\r\\n            document.getElementById('ctaText').value = state.ctaText;\\r\\n\\r\\n            updateMediaUI();\\r\\n            document.getElementById('startDate').value = state.startDate;\\r\\n            document.getElementById('endDate').value = state.endDate;\\r\\n\\r\\n            document.querySelectorAll('.channel-tabs .tab').forEach(btn =\\u003e {\\r\\n                const isActive = btn.dataset.tab === state.activeTab;\\r\\n                btn.className = `tab ${isActive ? 'active' : ''}`;\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function updateSummary() {\\r\\n            const sel = getSelectedType();\\r\\n            const start = new Date(state.startDate);\\r\\n            const end = new Date(state.endDate);\\r\\n            const days = daysBetween(start, end);\\r\\n            const metrics = calculateMetrics();\\r\\n\\r\\n            document.getElementById('summaryChannel').innerHTML =\\r\\n                `\\u003ci class=\\"${sel.icon}\\" style=\\"color:${sel.color}\\"\\u003e\\u003c/i\\u003e ${sel.name}`;\\r\\n            document.getElementById('summaryDuration').textContent = days + ' days';\\r\\n            document.getElementById('summaryDailyBudget').textContent = '$' + fmt(metrics.dailyBudget);\\r\\n            document.getElementById('summaryAudience').textContent = state.demographics.length + ' age groups';\\r\\n            document.getElementById('summaryLocations').textContent = state.locations.length + ' countries';\\r\\n            document.getElementById('summaryCpm').textContent = '$' + metrics.cpm;\\r\\n        }\\r\\n\\r\\n        function updateMetrics() {\\r\\n            const m = calculateMetrics();\\r\\n            document.getElementById('estImpressions').textContent = fmt(m.impressions);\\r\\n            document.getElementById('estCpm').textContent = 'CPM $' + m.cpm;\\r\\n            document.getElementById('estReach').textContent = fmt(m.reach);\\r\\n            document.getElementById('estFrequency').textContent = 'Freq: ' + m.frequency + 'x';\\r\\n        }\\r\\n\\r\\n        function updateMediaUI() {\\r\\n            const placeholder = document.getElementById('mediaPlaceholder');\\r\\n            const preview = document.getElementById('mediaPreview');\\r\\n            const img = document.getElementById('mediaImage');\\r\\n            if (state.mediaUrl) {\\r\\n                placeholder.classList.add('hidden');\\r\\n                preview.classList.remove('hidden');\\r\\n                img.src = state.mediaUrl;\\r\\n            } else {\\r\\n                placeholder.classList.remove('hidden');\\r\\n                preview.classList.add('hidden');\\r\\n                img.src = '';\\r\\n            }\\r\\n        }\\r\\n\\r\\n        // ============================================================\\r\\n        //  EVENT BINDING\\r\\n        // ============================================================\\r\\n\\r\\n        function init() {\\r\\n            const today = new Date();\\r\\n            state.startDate = formatDate(today);\\r\\n            state.endDate = formatDate(addDays(today, 30));\\r\\n            document.getElementById('startDate').value = state.startDate;\\r\\n            document.getElementById('endDate').value = state.endDate;\\r\\n\\r\\n            document.querySelectorAll('.channel-tabs .tab').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.activeTab = btn.dataset.tab;\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n\\r\\n            document.getElementById('campaignName').addEventListener('input', e =\\u003e { state.name = e.target.value;\\r\\n                updateAll(); });\\r\\n            document.getElementById('campaignObjective').addEventListener('change', e =\\u003e { state.objective = e.target\\r\\n                    .value;\\r\\n                updateAll(); });\\r\\n            document.getElementById('startDate').addEventListener('change', e =\\u003e { state.startDate = e.target.value;\\r\\n                updateAll(); });\\r\\n            document.getElementById('endDate').addEventListener('change', e =\\u003e { state.endDate = e.target.value;\\r\\n                updateAll(); });\\r\\n            document.getElementById('budgetRange').addEventListener('input', e =\\u003e { state.budget = Number(e.target.value);\\r\\n                updateAll(); });\\r\\n            document.getElementById('headline').addEventListener('input', e =\\u003e { state.headline = e.target.value;\\r\\n                updateAll(); });\\r\\n            document.getElementById('description').addEventListener('input', e =\\u003e { state.description = e.target.value;\\r\\n                updateAll(); });\\r\\n            document.getElementById('ctaText').addEventListener('input', e =\\u003e { state.ctaText = e.target.value;\\r\\n                updateAll(); });\\r\\n\\r\\n            const mediaDrop = document.getElementById('mediaDrop');\\r\\n            mediaDrop.addEventListener('click', () =\\u003e {\\r\\n                if (state.mediaUrl) { state.mediaUrl = ''; } else { state.mediaUrl = SAMPLE_IMAGES[Math.floor(Math\\r\\n                        .random() * SAMPLE_IMAGES.length)]; }\\r\\n                updateAll();\\r\\n            });\\r\\n            document.getElementById('removeMedia').addEventListener('click', (e) =\\u003e {\\r\\n                e.stopPropagation();\\r\\n                state.mediaUrl = '';\\r\\n                updateAll();\\r\\n            });\\r\\n\\r\\n            document.getElementById('launchBtn').addEventListener('click', function() {\\r\\n                if (state.isSubmitting) return;\\r\\n                state.isSubmitting = true;\\r\\n                this.disabled = true;\\r\\n                this.innerHTML =\\r\\n                    '\\u003cspan class=\\"flex items-center gap-2\\"\\u003e\\u003cspan class=\\"w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin\\"\\u003e\\u003c/span\\u003e Launching...\\u003c/span\\u003e';\\r\\n                setTimeout(() =\\u003e {\\r\\n                    state.isSubmitting = false;\\r\\n                    this.disabled = false;\\r\\n                    this.innerHTML = 'Launch Campaign';\\r\\n                    alert('🎉 Campaign launched successfully!');\\r\\n                }, 2000);\\r\\n            });\\r\\n\\r\\n            updateAll();\\r\\n        }\\r\\n\\r\\n        document.addEventListener('DOMContentLoaded', init);\\r\\n    \\u003c/script\\u003e\\r\\n\\r\\n\\u003c/body\\u003e\\r\\n\\r\\n              ","LayoutID":3,"CreatedAt":"2026-07-23T12:26:19.420888+07:00","UpdatedAt":"2026-07-23T16:32:41.755518+07:00","MetaTitle":"","MetaDescription":"","CanonicalURL":"","FocusKeyword":"","MetaRobotsNoindex":false,"MetaRobotsNofollow":false,"OGTitle":"","OGDescription":"","OGImage":"","TwitterCard":"","TwitterTitle":"","TwitterDescription":"","TwitterImage":""}	1	Admin	2026-07-23 16:54:48.927211+07
