}\\r\\n        }\\r\\n\\r\\n        .animate-spin {\\r\\n            animation: spin 0.7s linear infinite;\\r\\n        }\\r\\n\\r\\n        @keyframes spin {\\r\\n            to {\\r\\n                transform: rotate(360deg);\\r\\n            }\\r\\n        }\\r\\n\\r\\n        .animate-pulse {\\r\\n            animation: pulse 1.5s ease-in-out infinite;\\r\\n        }\\r\\n\\r\\n        @keyframes pulse {\\r\\n\\r\\n            0%,\\r\\n            100% {\\r\\n                opacity: 1;\\r\\n            }\\r\\n            50% {\\r\\n                opacity: 0.4;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        [type=\\"range\\"] {\\r\\n            -webkit-appearance: none;\\r\\n            appearance: none;\\r\\n            background: transparent;\\r\\n        }\\r\\n\\r\\n        [type=\\"range\\"]::-webkit-slider-runnable-track {\\r\\n            height: 5px;\\r\\n            background: #e5e7eb;\\r\\n            border-radius: 999px;\\r\\n        }\\r\\n\\r\\n        [type=\\"range\\"]::-webkit-slider-thumb {\\r\\n            -webkit-appearance: none;\\r\\n            appearance: none;\\r\\n            width: 16px;\\r\\n            height: 16px;\\r\\n            border-radius: 50%;\\r\\n            background: #2563eb;\\r\\n            cursor: pointer;\\r\\n            margin-top: -5.5px;\\r\\n            box-shadow: 0 2px 8px rgba(37, 99, 235, 0.4);\\r\\n        }\\r\\n\\r\\n        [type=\\"range\\"]::-moz-range-track {\\r\\n            height: 5px;\\r\\n            background: #e5e7eb;\\r\\n            border-radius: 999px;\\r\\n            border: none;\\r\\n        }\\r\\n\\r\\n        [type=\\"range\\"]::-moz-range-thumb {\\r\\n            width: 16px;\\r\\n            height: 16px;\\r\\n            border-radius: 50%;\\r\\n            background: #2563eb;\\r\\n            cursor: pointer;\\r\\n            border: none;\\r\\n        }\\r\\n\\r\\n        ::-webkit-scrollbar {\\r\\n            width: 5px;\\r\\n            height: 5px;\\r\\n        }\\r\\n\\r\\n        ::-webkit-scrollbar-track {\\r\\n            background: #f1f5f9;\\r\\n            border-radius: 999px;\\r\\n        }\\r\\n\\r\\n        ::-webkit-scrollbar-thumb {\\r\\n            background: #cbd5e1;\\r\\n            border-radius: 999px;\\r\\n        }\\r\\n\\r\\n        ::-webkit-scrollbar-thumb:hover {\\r\\n            background: #94a3b8;\\r\\n        }\\r\\n\\r\\n        .sticky-top {\\r\\n            position: sticky;\\r\\n            top: 0px;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 1024px) {\\r\\n            .sticky-top {\\r\\n                position: relative;\\r\\n                top: 0;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        /* bottom fixed bar */\\r\\n        .bottom-bar {\\r\\n            position: fixed;\\r\\n            bottom: 0;\\r\\n            left: 0;\\r\\n            right: 0;\\r\\n            z-index: 50;\\r\\n            background: rgba(255, 255, 255, 0.92);\\r\\n            backdrop-filter: blur(12px);\\r\\n            border-top: 1px solid #e5e7eb;\\r\\n            padding: 10px 20px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: space-between;\\r\\n            flex-wrap: wrap;\\r\\n            gap: 10px;\\r\\n        }\\r\\n\\r\\n        .bottom-bar .total-invest {\\r\\n            display: flex;\\r\\n            align-items: baseline;\\r\\n            gap: 6px;\\r\\n            font-size: 14px;\\r\\n            color: #6b7280;\\r\\n        }\\r\\n\\r\\n        .bottom-bar .total-invest strong {\\r\\n            font-size: 20px;\\r\\n            color: #1f2937;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 640px) {\\r\\n            .bottom-bar {\\r\\n                flex-direction: column;\\r\\n                align-items: stretch;\\r\\n                padding: 10px 16px;\\r\\n            }\\r\\n            .bottom-bar .total-invest {\\r\\n                justify-content: center;\\r\\n            }\\r\\n            .bottom-bar .actions {\\r\\n                justify-content: center;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        /* compact channel grid */\\r\\n        .channel-grid {\\r\\n            display: grid;\\r\\n            grid-template-columns: repeat(5, 1fr);\\r\\n            gap: 8px;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 640px) {\\r\\n            .channel-grid {\\r\\n                grid-template-columns: repeat(3, 1fr);\\r\\n            }\\r\\n        }\\r\\n\\r\\n        .channel-btn {\\r\\n            padding: 10px 6px;\\r\\n            border-radius: 10px;\\r\\n            border: 2px solid #e5e7eb;\\r\\n            background: #fff;\\r\\n            transition: all 0.2s;\\r\\n            text-align: center;\\r\\n            cursor: pointer;\\r\\n            font-size: 12px;\\r\\n            font-weight: 500;\\r\\n            color: #4b5563;\\r\\n            position: relative;\\r\\n        }\\r\\n\\r\\n        .channel-btn:hover {\\r\\n            border-color: #9ca3af;\\r\\n        }\\r\\n\\r\\n        .channel-btn.active {\\r\\n            border-color: #3b82f6;\\r\\n            background: #eff6ff;\\r\\n            color: #1d4ed8;\\r\\n            box-shadow: 0 4px 12px rgba(59, 130, 246, 0.15);\\r\\n        }\\r\\n\\r\\n        .channel-btn .icon-wrap {\\r\\n            width: 28px;\\r\\n            height: 28px;\\r\\n            border-radius: 8px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n            margin: 0 auto 4px;\\r\\n            font-size: 14px;\\r\\n        }\\r\\n\\r\\n        .channel-btn .check {\\r\\n            position: absolute;\\r\\n            top: 4px;\\r\\n            right: 4px;\\r\\n            width: 16px;\\r\\n            height: 16px;\\r\\n            border-radius: 50%;\\r\\n            background: #3b82f6;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n            color: #fff;\\r\\n            font-size: 9px;\\r\\n        }\\r\\n\\r\\n        /* compact cards */\\r\\n        .section-card {\\r\\n            border: 1px solid #e5e7eb;\\r\\n            border-radius: 12px;\\r\\n            background: #fff;\\r\\n            overflow: hidden;\\r\\n        }\\r\\n\\r\\n        .section-card .head {\\r\\n            padding: 8px 16px;\\r\\n            border-bottom: 1px solid #f3f4f6;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            gap: 10px;\\r\\n            font-weight: 600;\\r\\n            font-size: 14px;\\r\\n            color: #1f2937;\\r\\n        }\\r\\n\\r\\n        .section-card .head .icon-box {\\r\\n            width: 28px;\\r\\n            height: 28px;\\r\\n            border-radius: 8px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n            font-size: 14px;\\r\\n            flex-shrink: 0;\\r\\n        }\\r\\n\\r\\n        .section-card .body {\\r\\n            padding: 12px 16px;\\r\\n        }\\r\\n\\r\\n        .section-card .body .field {\\r\\n            margin-bottom: 10px;\\r\\n        }\\r\\n\\r\\n        .section-card .body .field:last-child {\\r\\n            margin-bottom: 0;\\r\\n        }\\r\\n\\r\\n        .section-card .body label {\\r\\n            font-size: 12px;\\r\\n            font-weight: 500;\\r\\n            color: #4b5563;\\r\\n            display: block;\\r\\n            margin-bottom: 3px;\\r\\n        }\\r\\n\\r\\n        .section-card .body input,\\r\\n        .section-card .body select,\\r\\n        .section-card .body textarea {\\r\\n            width: 100%;\\r\\n            padding: 6px 12px;\\r\\n            border: 1px solid #e5e7eb;\\r\\n            border-radius: 8px;\\r\\n            font-size: 13px;\\r\\n            transition: all 0.2s;\\r\\n            background: #fff;\\r\\n            color: #1f2937;\\r\\n        }\\r\\n\\r\\n        .section-card .body input:focus,\\r\\n        .section-card .body select:focus,\\r\\n        .section-card .body textarea:focus {\\r\\n            outline: none;\\r\\n            border-color: #3b82f6;\\r\\n            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);\\r\\n        }\\r\\n\\r\\n        .section-card .body textarea {\\r\\n            resize: vertical;\\r\\n            min-height: 50px;\\r\\n        }\\r\\n\\r\\n        .section-card .body .chip-group {\\r\\n            display: flex;\\r\\n            flex-wrap: wrap;\\r\\n            gap: 5px;\\r\\n        }\\r\\n\\r\\n        .section-card .body .chip {\\r\\n            padding: 4px 12px;\\r\\n            border-radius: 20px;\\r\\n            font-size: 12px;\\r\\n            font-weight: 500;\\r\\n            transition: all 0.2s;\\r\\n            cursor: pointer;\\r\\n            border: none;\\r\\n            background: #f3f4f6;\\r\\n            color: #4b5563;\\r\\n        }\\r\\n\\r\\n        .section-card .body .chip:hover {\\r\\n            background: #e5e7eb;\\r\\n        }\\r\\n\\r\\n        .section-card .body .chip.active {\\r\\n            background: #3b82f6;\\r\\n            color: #fff;\\r\\n            box-shadow: 0 2px 8px rgba(59, 130, 246, 0.25);\\r\\n        }\\r\\n\\r\\n        .section-card .body .chip.active-purple {\\r\\n            background: #7c3aed;\\r\\n            color: #fff;\\r\\n            box-shadow: 0 2px 8px rgba(124, 58, 237, 0.25);\\r\\n        }\\r\\n\\r\\n        .section-card .body .chip.active-indigo {\\r\\n            background: #4f46e5;\\r\\n            color: #fff;\\r\\n            box-shadow: 0 2px 8px rgba(79, 70, 229, 0.25);\\r\\n        }\\r\\n\\r\\n        .section-card .body .budget-row {\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            gap: 12px;\\r\\n        }\\r\\n\\r\\n        .section-card .body .budget-row input[type=\\"range\\"] {\\r\\n            flex: 1;\\r\\n            padding: 0;\\r\\n            border: none;\\r\\n            background: transparent;\\r\\n            box-shadow: none;\\r\\n        }\\r\\n\\r\\n        .section-card .body .budget-row .budget-val {\\r\\n            background: #f9fafb;\\r\\n            padding: 4px 14px;\\r\\n            border-radius: 8px;\\r\\n            font-weight: 600;\\r\\n            font-size: 15px;\\r\\n            color: #1f2937;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            gap: 4px;\\r\\n            border: 1px solid #e5e7eb;\\r\\n            white-space: nowrap;\\r\\n        }\\r\\n\\r\\n        .section-card .body .budget-row .budget-val i {\\r\\n            color: #9ca3af;\\r\\n            font-size: 12px;\\r\\n        }\\r\\n\\r\\n        .media-drop {\\r\\n            border: 2px dashed #e5e7eb;\\r\\n            border-radius: 10px;\\r\\n            padding: 16px;\\r\\n            text-align: center;\\r\\n            cursor: pointer;\\r\\n            transition: all 0.2s;\\r\\n        }\\r\\n\\r\\n        .media-drop:hover {\\r\\n            border-color: #60a5fa;\\r\\n            background: #eff6ff;\\r\\n        }\\r\\n\\r\\n        .media-drop .preview-img {\\r\\n            max-height: 80px;\\r\\n            margin: 0 auto;\\r\\n            border-radius: 6px;\\r\\n            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);\\r\\n        }\\r\\n\\r\\n        .media-drop .placeholder-icon {\\r\\n            width: 40px;\\r\\n            height: 40px;\\r\\n            background: #f3f4f6;\\r\\n            border-radius: 50%;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n            margin: 0 auto 6px;\\r\\n            color: #9ca3af;\\r\\n            font-size: 18px;\\r\\n        }\\r\\n\\r\\n        .preview-card .preview-inner {\\r\\n            padding: 12px;\\r\\n            background: linear-gradient(to bottom, #f9fafb, #ffffff);\\r\\n            min-height: 220px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            justify-content: center;\\r\\n        }\\r\\n\\r\\n        .summary-grid {\\r\\n            display: grid;\\r\\n            grid-template-columns: 1fr 1fr;\\r\\n            gap: 4px 16px;\\r\\n        }\\r\\n\\r\\n        .summary-grid .item {\\r\\n            display: flex;\\r\\n            justify-content: space-between;\\r\\n            padding: 4px 0;\\r\\n            border-bottom: 1px solid #f3f4f6;\\r\\n            font-size: 13px;\\r\\n        }\\r\\n\\r\\n        .summary-grid .item .label {\\r\\n            color: #6b7280;\\r\\n        }\\r\\n\\r\\n        .summary-grid .item .value {\\r\\n            font-weight: 500;\\r\\n            color: #1f2937;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            gap: 4px;\\r\\n        }\\r\\n\\r\\n        .perf-grid {\\r\\n            display: grid;\\r\\n            grid-template-columns: 1fr 1fr;\\r\\n            gap: 8px;\\r\\n        }\\r\\n\\r\\n        .perf-grid .box {\\r\\n            background: rgba(255, 255, 255, 0.06);\\r\\n            border-radius: 10px;\\r\\n            padding: 10px 12px;\\r\\n        }\\r\\n\\r\\n        .perf-grid .box .num {\\r\\n            font-size: 22px;\\r\\n            font-weight: 700;\\r\\n            color: #fff;\\r\\n        }\\r\\n\\r\\n        .perf-grid .box .num.green {\\r\\n            color: #4ade80;\\r\\n        }\\r\\n\\r\\n        .perf-grid .box .sub {\\r\\n            font-size: 11px;\\r\\n            color: #9ca3af;\\r\\n            margin-top: 2px;\\r\\n            display: flex;\\r\\n            align-items: center;\\r\\n            gap: 4px;\\r\\n        }\\r\\n\\r\\n        .perf-grid .box .sub i {\\r\\n            font-size: 10px;\\r\\n        }\\r\\n\\r\\n        .tip-box {\\r\\n            background: #eff6ff;\\r\\n            border-radius: 10px;\\r\\n            padding: 10px 14px;\\r\\n            border: 1px solid #bfdbfe;\\r\\n            display: flex;\\r\\n            gap: 10px;\\r\\n            align-items: flex-start;\\r\\n        }\\r\\n\\r\\n        .tip-box i {\\r\\n            color: #2563eb;\\r\\n            margin-top: 2px;\\r\\n            font-size: 14px;\\r\\n        }\\r\\n\\r\\n        .tip-box .content {\\r\\n            font-size: 12px;\\r\\n            color: #1e40af;\\r\\n        }\\r\\n\\r\\n        .tip-box .content strong {\\r\\n            font-weight: 600;\\r\\n        }\\r\\n\\r\\n        body {\\r\\n            padding-bottom: 80px;\\r\\n            background: #f8fafc;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 640px) {\\r\\n            body {\\r\\n                padding-bottom: 120px;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        .main-wrap {\\r\\n            max-width: 1280px;\\r\\n            margin: 0 auto;\\r\\n            padding: 12px 16px 0;\\r\\n        }\\r\\n\\r\\n        .grid-main {\\r\\n            display: grid;\\r\\n            grid-template-columns: 1fr 380px;\\r\\n            gap: 20px;\\r\\n            align-items: start;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 1024px) {\\r\\n            .grid-main {\\r\\n                grid-template-columns: 1fr;\\r\\n            }\\r\\n            .right-col {\\r\\n                order: -1;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        .right-col {\\r\\n            position: sticky;\\r\\n            top: 8px;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 1024px) {\\r\\n            .right-col {\\r\\n                position: relative;\\r\\n                top: 0;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        .left-col {\\r\\n            max-height: calc(100vh - 120px);\\r\\n            overflow-y: auto;\\r\\n            padding-right: 4px;\\r\\n        }\\r\\n\\r\\n        @media (max-width: 1024px) {\\r\\n            .left-col {\\r\\n                max-height: none;\\r\\n                overflow-y: visible;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        .left-col::-webkit-scrollbar {\\r\\n            width: 4px;\\r\\n        }\\r\\n\\r\\n        .left-col::-webkit-scrollbar-thumb {\\r\\n            background: #d1d5db;\\r\\n            border-radius: 999px;\\r\\n        }\\r\\n\\r\\n        .section-card+.section-card {\\r\\n            margin-top: 10px;\\r\\n        }\\r\\n\\r\\n        .compact-date {\\r\\n            display: grid;\\r\\n            grid-template-columns: 1fr 1fr;\\r\\n            gap: 10px;\\r\\n        }\\r\\n\\r\\n        .channel-tabs {\\r\\n            display: flex;\\r\\n            flex-wrap: wrap;\\r\\n            gap: 4px;\\r\\n            margin-bottom: 8px;\\r\\n        }\\r\\n\\r\\n        .channel-tabs .tab {\\r\\n            padding: 3px 12px;\\r\\n            border-radius: 20px;\\r\\n            font-size: 11px;\\r\\n            font-weight: 500;\\r\\n            cursor: pointer;\\r\\n            transition: all 0.2s;\\r\\n            border: none;\\r\\n            background: #f3f4f6;\\r\\n            color: #4b5563;\\r\\n        }\\r\\n\\r\\n        .channel-tabs .tab:hover {\\r\\n            background: #e5e7eb;\\r\\n        }\\r\\n\\r\\n        .channel-tabs .tab.active {\\r\\n            background: #1f2937;\\r\\n            color: #fff;\\r\\n        }\\r\\n\\r\\n        .scroll-fix {\\r\\n            scroll-margin-top: 0;\\r\\n        }\\r\\n    \\u003c/style\\u003e\\r\\n\\u003c/head\\u003e\\r\\n\\u003cbody\\u003e\\r\\n\\r\\n    \\u003c!-- ===== MAIN WRAP ===== --\\u003e\\r\\n    \\u003cdiv class=\\"main-wrap\\"\\u003e\\r\\n\\r\\n        \\u003cdiv class=\\"grid-main\\"\\u003e\\r\\n\\r\\n            \\u003c!-- ===== LEFT COLUMN ===== --\\u003e\\r\\n            \\u003cdiv class=\\"left-col\\" id=\\"leftCol\\"\\u003e\\r\\n\\r\\n                \\u003c!-- Campaign Channel --\\u003e\\r\\n                \\u003cdiv class=\\"section-card\\"\\u003e\\r\\n                    \\u003cdiv class=\\"head\\"\\u003e\\r\\n                        \\u003cdiv class=\\"icon-box bg-violet-50 text-violet-600\\"\\u003e\\u003ci class=\\"fas fa-layer-group\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cspan\\u003eChannel\\u003c/span\\u003e\\r\\n                        \\u003cspan class=\\"text-xs font-normal text-gray-400 ml-auto\\"\\u003ePick your ad platform\\u003c/span\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                    \\u003cdiv class=\\"body\\"\\u003e\\r\\n                        \\u003c!-- tabs --\\u003e\\r\\n                        \\u003cdiv class=\\"channel-tabs\\"\\u003e\\r\\n                            \\u003cbutton data-tab=\\"all\\" class=\\"tab active\\"\\u003eAll\\u003c/button\\u003e\\r\\n                            \\u003cbutton data-tab=\\"messaging\\" class=\\"tab\\"\\u003eMessaging\\u003c/button\\u003e\\r\\n                            \\u003cbutton data-tab=\\"social\\" class=\\"tab\\"\\u003eSocial\\u003c/button\\u003e\\r\\n                            \\u003cbutton data-tab=\\"programmatic\\" class=\\"tab\\"\\u003eProgrammatic\\u003c/button\\u003e\\r\\n                            \\u003cbutton data-tab=\\"outdoor\\" class=\\"tab\\"\\u003eOutdoor\\u003c/button\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                        \\u003c!-- grid --\\u003e\\r\\n                        \\u003cdiv id=\\"channelGrid\\" class=\\"channel-grid\\"\\u003e\\r\\n                            \\u003c!-- rendered by JS --\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n\\r\\n                \\u003c!-- Campaign Info + Schedule + Budget in one compact row --\\u003e\\r\\n                \\u003cdiv class=\\"section-card\\"\\u003e\\r\\n                    \\u003cdiv class=\\"head\\"\\u003e\\r\\n                        \\u003cdiv class=\\"icon-box bg-blue-50 text-blue-600\\"\\u003e\\u003ci class=\\"fas fa-bullhorn\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cspan\\u003eCampaign\\u003c/span\\u003e\\r\\n                        \\