e\\" type=\\"date\\" /\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                            \\u003cdiv class=\\"field\\"\\u003e\\r\\n                                \\u003clabel\\u003eEnd\\u003c/label\\u003e\\r\\n                                \\u003cinput id=\\"endDate\\" type=\\"date\\" /\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                        \\u003cdiv class=\\"field\\"\\u003e\\r\\n                            \\u003clabel\\u003eBudget (USD)\\u003c/label\\u003e\\r\\n                            \\u003cdiv class=\\"budget-row\\"\\u003e\\r\\n                                \\u003cinput id=\\"budgetRange\\" type=\\"range\\" min=\\"100\\" max=\\"100000\\" step=\\"100\\" value=\\"5000\\" /\\u003e\\r\\n                                \\u003cdiv class=\\"budget-val\\"\\u003e\\u003ci class=\\"fas fa-dollar-sign\\"\\u003e\\u003c/i\\u003e \\u003cspan id=\\"budgetDisplay\\"\\u003e5,000\\u003c/span\\u003e\\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                \\u003c/div\\u003e\\r\\n\\r\\n                \\u003c!-- Audience Targeting --\\u003e\\r\\n                \\u003cdiv class=\\"section-card\\"\\u003e\\r\\n                    \\u003cdiv class=\\"head\\"\\u003e\\r\\n                        \\u003cdiv class=\\"icon-box bg-rose-50 text-rose-600\\"\\u003e\\u003ci class=\\"fas fa-crosshairs\\"\\u003e\\u003c/i\\u003e\\u003c/div\\u003e\\r\\n                        \\u003cspan\\u003eAudience\\u003c/span\\u003e\\r\\n                        \\u003cspan class=\\"text-xs font-normal text-gray-400 ml-auto\\"\\u003eAge · Gender · Location · Interests\\u003c/span\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n                    \\u003cdiv class=\\"body\\"\\u003e\\r\\n                        \\u003cdiv class=\\"field\\"\\u003e\\r\\n                 