=\\"num green\\" id=\\"estReach\\"\\u003e750,000\\u003c/div\\u003e\\r\\n                                \\u003cdiv class=\\"sub\\"\\u003e\\u003ci class=\\"fas fa-users text-gray-400\\"\\u003e\\u003c/i\\u003e \\u003cspan id=\\"estFrequency\\"\\u003eFreq: 1.7x\\u003c/span\\u003e\\u003c/div\\u003e\\r\\n                            \\u003c/div\\u003e\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n\\r\\n                    \\u003c!-- Tip --\\u003e\\r\\n                    \\u003cdiv class=\\"tip-box\\"\\u003e\\r\\n                        \\u003ci class=\\"fas fa-sparkles\\"\\u003e\\u003c/i\\u003e\\r\\n                        \\u003cdiv class=\\"content\\"\\u003e\\r\\n                            \\u003cstrong\\u003eOptimization Tip\\u003c/strong\\u003e\\u003cbr /\\u003e\\r\\n                            Your current targeting reaches a broad audience. Consider narrowing down locations for better ROI.\\r\\n                        \\u003c/div\\u003e\\r\\n                    \\u003c/div\\u003e\\r\\n\\r\\n                \\u003c/div\\u003e\\r\\n            \\u003c/div\\u003e\\r\\n\\r\\n        \\u003c/div\\u003e\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n    \\u003c!-- ===== BOTTOM FIXED BAR ===== --\\u003e\\r\\n    \\u003cdiv class=\\"bottom-bar\\"\\u003e\\r\\n        \\u003cdiv class=\\"total-invest\\"\\u003e\\r\\n            \\u003cspan\\u003eTotal Investment\\u003c/span\\u003e\\r\\n            \\u003cstrong id=\\"bottomTotal\\"\\u003eRp 50,000\\u003c/strong\\u003e\\r\\n        \\u003c/div\\u003e\\r\\n        \\u003cdiv class=\\"actions flex items-center gap-3\\"\\u003e\\r\\n            \\u003cbutton class=\\"px-5 py-2 text-sm font-medium text-gray-700 hover:text-gray-900 transition-colors border border-gray-300 rounded-lg hover:bg-gray-50\\"\\u003e\\r\\n                Save Draft\\r\\n            \\u003c/button\\u003e\\r\\n            \\u003cbutton id=\\"launchBtn\\" class=\\"px-6 py-2.5 rounded-lg text-sm font-semibold text-white transition-all duration-200 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 shadow-lg shadow-blue-200 hover:shadow-xl hover:shadow-blue-300 disabled:opacity-50 disabled:cursor-not-allowed\\"\\u003e\\r\\n                Launch Campaign\\r\\n            \\u003c/button\\u003e\\r\\n        \\u003c/div\\u003e\\r\\n    \\u003c/div\\u003e\\r\\n\\r\\n    \\u003c!-- ===== JAVASCRIPT ===== --\\u003e\\r\\n    \\u003cscript\\u003e\\r\\n        // ============================================================\\r\\n        //  DATA — Combined Programmatic into one option\\r\\n        // ============================================================\\r\\n\\r\\n        const CAMPAIGN_TYPES = [\\r\\n            { id: 'whatsapp', name: 'WhatsApp', icon: 'fa-brands fa-whatsapp', color: '#25D366', category: 'messaging' },\\r\\n            { id: 'sms', name: 'SMS', icon: 'fas fa-mobile-alt', color: '#3B82F6', category: 'messaging' },\\r\\n            { id: 'rcs', name: 'RCS', icon: 'fas fa-comment', color: '#F59E0B', category: 'messaging' },\\r\\n            { id: 'ooh', name: 'OOH', icon: 'fas fa-building', color: '#10B981', category: 'outdoor' },\\r\\n            { id: 'dooh', name: 'DOOH', icon: 'fas fa-desktop', color: '#8B5CF6', category: 'outdoor' },\\r\\n            // Combined Programmatic\\r\\n            { id: 'programmatic', name: 'Programmatic Ads', icon: 'fas fa-ad', color: '#F97316', category: 'programmatic' },\\r\\n            { id: 'meta', name: 'Meta Ads', icon: 'fa-brands fa-facebook', color: '#1877F2', category: 'social' },\\r\\n            { id: 'gdn', name: 'YouTube', icon: 'fa-brands fa-youtube', color: '#FF0000', category: 'social' },\\r\\n            { id: 'tiktok', name: 'TikTok', icon: 'fa-brands fa-tiktok', color: '#000000', category: 'social' },\\r\\n        ];\\r\\n\\r\\n        const DEMOGRAPHICS = [\\r\\n            { id: '18-24', label: '18-24', multiplier: 1.0 },\\r\\n            { id: '25-34', label: '25-34', multiplier: 1.1 },\\r\\n            { id: '35-44', label: '35-44', multiplier: 1.2 },\\r\\n            { id: '45-54', label: '45-54', multiplier: 1.1 },\\r\\n            { id: '55-64', label: '55-64', multiplier: 0.9 },\\r\\n            { id: '65+', label: '65+', multiplier: 0.8 },\\r\\n        ];\\r\\n\\r\\n        const GENDERS = [\\r\\n            { id: 'all', label: 'All' },\\r\\n            { id: 'male', label: 'Male' },\\r\\n            { id: 'female', label: 'Female' },\\r\\n        ];\\r\\n\\r\\n        const LOCATIONS = [\\r\\n            { id: 'us', label: 'US', multiplier: 1.5 },\\r\\n            { id: 'uk', label: 'UK', multiplier: 1.4 },\\r\\n            { id: 'de', label: 'DE', multiplier: 1.3 },\\r\\n            { id: 'fr', label: 'FR', multiplier: 1.2 },\\r\\n            { id: 'id', label: 'ID', multiplier: 0.6 },\\r\\n            { id: 'sg', label: 'SG', multiplier: 1.4 },\\r\\n            { id: 'my', label: 'MY', multiplier: 0.7 },\\r\\n            { id: 'th', label: 'TH', multiplier: 0.6 },\\r\\n            { id: 'ph', label: 'PH', multiplier: 0.5 },\\r\\n            { id: 'global', label: 'Global', multiplier: 1.0 },\\r\\n        ];\\r\\n\\r\\n        const INTERESTS = ['technology', 'lifestyle', 'fashion', 'sports', 'travel', 'food', 'music', 'gaming'];\\r\\n\\r\\n        const BASE_CPM_RATES = {\\r\\n            whatsapp: 0.05,\\r\\n            sms: 0.03,\\r\\n            rcs: 0.08,\\r\\n            ooh: 15,\\r\\n            dooh: 25,\\r\\n            programmatic: 3.5, // blended rate for combined programmatic\\r\\n            meta: 8,\\r\\n            gdn: 3,\\r\\n            tiktok: 6,\\r\\n        };\\r\\n\\r\\n        const SAMPLE_IMAGES = [\\r\\n            'https://images.unsplash.com/photo-1557804506-669a67965ba0?w=600\\u0026h=400\\u0026fit=crop',\\r\\n            'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=600\\u0026h=400\\u0026fit=crop',\\r\\n            'https://images.unsplash.com/photo-1551434678-e076c223a692?w=600\\u0026h=400\\u0026fit=crop',\\r\\n            'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=600\\u0026h=400\\u0026fit=crop',\\r\\n        ];\\r\\n\\r\\n        // ============================================================\\r\\n        //  STATE\\r\\n        // ============================================================\\r\\n\\r\\n        const state = {\\r\\n            type: 'meta',\\r\\n            activeTab: 'all',\\r\\n            name: 'Summer Blast 2024',\\r\\n            objective: 'engagement',\\r\\n            startDate: '',\\r\\n            endDate: '',\\r\\n            budget: 5000,\\r\\n            demographics: ['25-34', '35-44'],\\r\\n            gender: 'all',\\r\\n            locations: ['us', 'uk'],\\r\\n            interests: ['technology', 'lifestyle'],\\r\\n            headline: 'Transform Your Business Today',\\r\\n            description: 'Discover innovative solutions that help you grow faster and reach more customers effortlessly.',\\r\\n            ctaText: 'Learn More',\\r\\n            mediaUrl: '',\\r\\n            isSubmitting: false,\\r\\n        };\\r\\n\\r\\n        // ============================================================\\r\\n        //  HELPERS\\r\\n        // ============================================================\\r\\n\\r\\n        function fmt(n) { return n.toLocaleString(); }\\r\\n\\r\\n        function pad(n) { return String(n).padStart(2, '0'); }\\r\\n\\r\\n        function formatDate(d) {\\r\\n            return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());\\r\\n        }\\r\\n\\r\\n        function addDays(d, n) {\\r\\n            const r = new Date(d);\\r\\n            r.setDate(r.getDate() + n);\\r\\n            return r;\\r\\n        }\\r\\n\\r\\n        function daysBetween(a, b) {\\r\\n            return Math.max(1, Math.ceil((b.getTime() - a.getTime()) / (1000 * 60 * 60 * 24)));\\r\\n        }\\r\\n\\r\\n        function getSelectedType() {\\r\\n            return CAMPAIGN_TYPES.find(t =\\u003e t.id === state.type) || CAMPAIGN_TYPES[0];\\r\\n        }\\r\\n\\r\\n        function getFilteredTypes() {\\r\\n            return state.activeTab === 'all' ?\\r\\n                CAMPAIGN_TYPES :\\r\\n                CAMPAIGN_TYPES.filter(t =\\u003e t.category === state.activeTab);\\r\\n        }\\r\\n\\r\\n        function calculateMetrics() {\\r\\n            const baseCpm = BASE_CPM_RATES[state.type] || 5;\\r\\n            const start = new Date(state.startDate);\\r\\n            const end = new Date(state.endDate);\\r\\n            const days = daysBetween(start, end);\\r\\n\\r\\n            let multiplier = 1;\\r\\n            const demoMult = state.demographics.map(d =\\u003e DEMOGRAPHICS.find(dm =\\u003e dm.id === d)?.multiplier || 1);\\r\\n            multiplier *= demoMult.length \\u003e 0 ? demoMult.reduce((a, b) =\\u003e a + b, 0) / demoMult.length : 1;\\r\\n\\r\\n            const locMult = state.locations.map(l =\\u003e LOCATIONS.find(lm =\\u003e lm.id === l)?.multiplier || 1);\\r\\n            multiplier *= locMult.length \\u003e 0 ? Math.max(...locMult) : 1;\\r\\n\\r\\n            const finalCpm = baseCpm * multiplier;\\r\\n            const impressions = Math.round((state.budget / finalCpm) * 1000);\\r\\n            const reach = Math.round(impressions * 0.6);\\r\\n            const frequency = (impressions / reach).toFixed(1);\\r\\n\\r\\n            return {\\r\\n                cpm: finalCpm.toFixed(2),\\r\\n                impressions,\\r\\n                reach,\\r\\n                frequency,\\r\\n                dailyBudget: Math.round(state.budget / days),\\r\\n                days,\\r\\n            };\\r\\n        }\\r\\n\\r\\n        function toggleItem(arr, item) {\\r\\n            return arr.includes(item) ? arr.filter(x =\\u003e x !== item) : [...arr, item];\\r\\n        }\\r\\n\\r\\n        // ============================================================\\r\\n        //  RENDER FUNCTIONS\\r\\n        // ===