demo]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.demographics = toggleItem(state.demographics, btn.dataset.demo);\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderGenders() {\\r\\n            const container = document.getElementById('genderGroup');\\r\\n            container.innerHTML = GENDERS.map(g =\\u003e {\\r\\n                const active = state.gender === g.id;\\r\\n                return `\\u003cbutton data-gender=\\"${g.id}\\" class=\\"chip ${active ? 'active' : ''}\\"\\u003e${g.label}\\u003c/button\\u003e`;\\r\\n            }).join('');\\r\\n            container.querySelectorAll('[data-gender]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.gender = btn.dataset.gender;\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderLocations() {\\r\\n            const container = document.getElementById('locationGroup');\\r\\n            container.innerHTML = LOCATIONS.map(l =\\u003e {\\r\\n                const active = state.locations.includes(l.id);\\r\\n                return `\\u003cbutton data-loc=\\"${l.id}\\" class=\\"chip ${active ? 'active-indigo' : ''}\\"\\u003e${l.label}\\u003c/button\\u003e`;\\r\\n            }).join('');\\r\\n            container.querySelectorAll('[data-loc]').forEach(btn =\\u003e {\\r\\n                btn.addEventListener('click', () =\\u003e {\\r\\n                    state.locations = toggleItem(state.locations, btn.dataset.loc);\\r\\n                    updateAll();\\r\\n                });\\r\\n            });\\r\\n        }\\r\\n\\r\\n        function renderInterests() {\\r\\n            const container = document.getElementById('interestGroup');\\r\\n            container.innerHTML = INTERESTS.map(i =\\u003e {\\r\\n